<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('sales-lines'),tpl=document.getElementById('sales-line-template');let i=1;document.getElementById('add-sales-line').addEventListener('click',()=>list.insertAdjacentHTML('beforeend',tpl.innerHTML.replaceAll('__INDEX__',String(i++))));list.addEventListener('click',e=>{const b=e.target.closest('.remove-sales-line');if(b&&list.querySelectorAll('.sales-line').length>1)b.closest('.sales-line').remove();});});</script></section>
